// HMO Performance System: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const Z = 1.5, DUP_DAYS = 7, mean = a => a.reduce((s, x) => s + x, 0) / a.length;
const days = (a, b) => (new Date(b) - new Date(a)) / 864e5;
const byP = {};
for (const r of input) (byP[r.provider] = byP[r.provider] || []).push(r);
const k = Object.fromEntries(Object.entries(byP).map(([p, rs]) => { const d = rs.filter(r => r.decided);
  return [p, { claims: rs.length, avg: mean(rs.map(r => +r.amount)), approval: d.length ? d.filter(r => r.status === 'approved').length / d.length : 0,
    tat: d.length ? mean(d.map(r => days(r.submitted, r.decided))) : null }]; }));
const avgs = Object.values(k).map(v => v.avg), mu = mean(avgs), sd = Math.sqrt(mean(avgs.map(x => (x - mu) ** 2))) || 1;
const outliers = Object.entries(k).filter(([, v]) => (v.avg - mu) / sd > Z).map(([p, v]) => `${p}: cost per claim ${((v.avg - mu) / sd).toFixed(2)} SD above network`);
const seen = {}, dups = [];
for (const r of [...input].sort((a, b) => a.submitted.localeCompare(b.submitted))) {
  const key = [r.enrollee, r.provider, r.diagnosis, r.amount].join('|');
  if (seen[key] && days(seen[key].submitted, r.submitted) <= DUP_DAYS) dups.push(`${seen[key].claim_id} and ${r.claim_id}`);
  seen[key] = r; }
const decided = input.filter(r => r.decided), total = input.reduce((s, r) => s + +r.amount, 0), enrollees = new Set(input.map(r => r.enrollee)).size;
const report = [`Claims: ${input.length} from ${Object.keys(k).length} providers, ${enrollees} enrollees`,
  `Total claimed: NGN ${total.toLocaleString()} (NGN ${Math.round(total / enrollees).toLocaleString()} per enrollee)`,
  `Approval rate: ${Math.round(decided.filter(r => r.status === 'approved').length / decided.length * 100)}%`,
  `Average turnaround: ${mean(decided.map(r => days(r.submitted, r.decided))).toFixed(1)} days`, `Pending: ${input.length - decided.length}`, '',
  'Actions:', ...outliers.map(o => '- Review ' + o), ...dups.map(d => '- Possible duplicate: ' + d)].join('\n');
return [{ json: { outliers: outliers.length, duplicates: dups, report } }];
